# Ancestry Genealogy API
import requests

ANCESTRY_API_KEY = "CollegeDescriptionDetailSerializer"
BASE_URL = "https://api.ancestry.com/v1"

def search_ancestry(first_name, last_name, birth_year=None, country=None):
    """Search for ancestors"""
    params = {
        "firstName": first_name,
        "lastName": last_name,
        "api_key": ANCESTRY_API_KEY
    }
    if birth_year:
        params["birthYear"] = birth_year
    if country:
        params["country"] = country

    response = requests.get(f"{BASE_URL}/search", params=params)
    return response.json()

def get_census_record(record_id):
    """Get specific census record"""
    response = requests.get(
        f"{BASE_URL}/census/{record_id}",
        headers={"Authorization": f"Bearer {ANCESTRY_API_KEY}"}
    )
    return response.json()

def build_family_tree(member_ids):
    """Build a family tree from member IDs"""
    response = requests.post(
        f"{BASE_URL}/tree",
        headers={"Authorization": f"Bearer {ANCESTRY_API_KEY}"},
        json={"members": member_ids}
    )
    return response.json()
